public class ArchitectureTests
{
    [Fact]
    public void Domain_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Payment).Assembly)
            .That().ResideInNamespace("Payments.Domain")
            .ShouldNot().HaveDependencyOnAny("Payments.Infrastructure", "Microsoft.EntityFrameworkCore", "Confluent.Kafka")
            .GetResult();
        Assert.True(result.IsSuccessful, string.Join(", ", result.FailingTypeNames ?? []));
    }

    [Fact]   // ADR-042: only the outbox relay may publish to Kafka
    public void Only_outbox_relay_uses_kafka_producer()
    {
        var result = Types.InCurrentDomain()
            .That().HaveDependencyOn("Confluent.Kafka")
            .Should().ResideInNamespace("Payments.Infrastructure.Outbox")
            .GetResult();
        Assert.True(result.IsSuccessful, "ADR-042 violated by: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
