public async Task<Schedule> GetScheduleAsync(string loanId, CancellationToken ct)
{
    var legacyTask = legacy.GetScheduleAsync(loanId, ct);
    var modernTask = modern.GetScheduleAsync(loanId, ct);
    var legacyResult = await legacyTask;
    try { comparer.Record(loanId, legacyResult, await modernTask); } catch (Exception ex) { log.LogWarning(ex, "Shadow failed"); }
    return legacyResult;                                   // switch to modern once mismatch rate is 0 for 4 weeks
}
