// Core idea from the design: idempotent settlement step keyed by business id, recorded atomically with the posting
public async Task HandleAsync(PaymentCleared evt, CancellationToken ct)
{
    await using var tx = await db.Database.BeginTransactionAsync(ct);
    if (await db.ProcessedMessages.AnyAsync(m => m.MessageId == evt.MessageId, ct)) return;   // duplicate delivery

    db.LedgerPostings.AddRange(Posting.For(evt));                                              // double-entry pair
    db.Outbox.Add(OutboxMessage.From(new SettlementInstructed(evt.PaymentId, evt.Amount, evt.Currency)));
    db.ProcessedMessages.Add(new ProcessedMessage(evt.MessageId));

    await db.SaveChangesAsync(ct);
    await tx.CommitAsync(ct);
}
